-- #262: seed the "Ourco Editorial" builder template (design blocks: sections, eyebrow,
-- display heading, milestones, steps list, button + text link). Idempotent: inserts only
-- when no template has that name yet, so running it again changes nothing.
-- The JSON is src/lib/editorial-template.ts editorialTemplateBlocks(), sanitised; a test
-- keeps the two identical. Own header section, so the global header is off; footer on.
INSERT INTO templates (name, kind, blocks, use_global_header, use_global_footer)
SELECT 'Ourco Editorial', 'builder', '[{"id":"ed-header","type":"section","bg":"#191919","padding":"sm","width":"full","blocks":[{"id":"ed-logo","type":"image","src":"https://crm.myapp.example/icons/icon-512.png","alt":"Ourco","href":"https://ourco.example","width":40,"beside":"Ourco"}],"color":"#ffffff","align":"center"},{"id":"ed-hero","type":"section","bg":"#1a9ec4","padding":"lg","width":"full","blocks":[{"id":"ed-chip","type":"image","src":"https://crm.myapp.example/icons/icon-512.png","alt":"Ourco","width":48,"style":"chip"},{"id":"ed-eyebrow","type":"eyebrow","content":[{"type":"text","text":"Campaign label"}]},{"id":"ed-headline","type":"heading","level":1,"text":"Your big, bold headline goes here.","content":[{"type":"text","text":"Your big, bold headline goes here."}],"size":"display"},{"id":"ed-intro","type":"paragraph","content":[{"type":"text","text":"Intro paragraph: one or two sentences on why this email matters and what the reader should do next."}]},{"id":"ed-milestones","type":"milestones","items":[{"title":[{"type":"text","text":"Step 1"}],"label":[{"type":"text","text":"Label"}]},{"title":[{"type":"text","text":"Step 2"}],"label":[{"type":"text","text":"Label"}]},{"title":[{"type":"text","text":"Step 3"}],"label":[{"type":"text","text":"Label"}]},{"title":[{"type":"text","text":"Step 4"}],"label":[{"type":"text","text":"Label"}]}],"rule":true},{"id":"ed-cta","type":"button","label":"Book a call","href":"https://ourco.example/book/","align":"left","linkLabel":"ourco.example/book/","linkHref":"https://ourco.example/book/"}],"color":"#000000"},{"id":"ed-body","type":"section","bg":"#ffffff","padding":"lg","width":"full","blocks":[{"id":"ed-content","type":"content"},{"id":"ed-steps","type":"list","ordered":true,"items":[[{"type":"text","text":"First step: what happens first, in a sentence."}],[{"type":"text","text":"Second step: what the reader can expect next."}],[{"type":"text","text":"Third step: the outcome. Delete this list if you do not need it."}]],"style":"steps"}],"color":"#333333"}]', 0, 1
WHERE NOT EXISTS (SELECT 1 FROM templates WHERE name = 'Ourco Editorial');
